import functools, sys
sys.setrecursionlimit(10**6)
def climb(n, big=2):
    calls = 0
    @functools.cache
    def ways(k):
        nonlocal calls
        calls += 1
        if k < 0:
            return 0
        if k == 0:
            return 1
        return ways(k - 1) + ways(k - big)
    return ways(n), calls
print(climb(4), climb(4, big=3), climb(3000)[0] % 1000)
